const tabId = 730410078;

async function getJobsOnPage(pg) {
  const url = `https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&q=chef&pg=${pg}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    // Each job result on OhioMeansJobs has a container
    const items = Array.from(document.querySelectorAll('.search__item, .job-item, [id*="rptResults"]')).map(item => {
      const title = item.querySelector('h3, a[id*="topTitle"]')?.textContent.trim().replace(/\s+/g, ' ');
      const titleLink = item.querySelector('a[id*="topTitle"]')?.href;
      const company = item.querySelector('.company, [id*="Company"], a[href*="Company"]')?.textContent.trim();
      const location = item.querySelector('.location, [id*="Location"], a[href*="Location"]')?.textContent.trim();
      const detailedLink = item.querySelector('a[href*="Detail.aspx"], a[title*="Detailed"]')?.href;
      const fullText = item.textContent.trim().replace(/\s+/g, ' ');
      return { title, titleLink, company, location, detailedLink, fullText };
    });
    return items;
  });
}

const p1 = await getJobsOnPage(1);
const p2 = await getJobsOnPage(2);
const allJobs = [...p1, ...p2];
console.log(JSON.stringify(allJobs, null, 2));

