const tabId = 730410078;
const facets = await browserjs(tabId, () => {
  const refine = document.getElementById('sr-refine');
  if (!refine) return "no refine";
  const h5s = Array.from(refine.querySelectorAll('h5')).map(h => {
    const title = h.textContent.trim();
    const ul = h.nextElementSibling;
    const links = ul ? Array.from(ul.querySelectorAll('li')).map(li => ({
      text: li.textContent.trim().replace(/\s+/g, ' '),
      onclick: li.querySelector('a')?.getAttribute('onclick')
    })) : [];
    return { title, links };
  });
  return h5s;
});
console.log(JSON.stringify(facets, null, 2));

