const tabId = 730410078;

const tests = [
  // 1. occ=35101100, no keyword
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&omjindustry=72&jt=5&cjfcso=1&occ=35101100",
  // 2. tjt=chef, no keyword
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&omjindustry=72&jt=5&cjfcso=1&tjt=chef",
  // 3. no keyword, just industry, jt=5, cjfcso=1
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&omjindustry=72&jt=5&cjfcso=1",
  // 4. without cjfcso=1, but with q=chef, omjindustry=72, jt=5
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&omjindustry=72&jt=5&q=chef",
  // 5. without jt=5, but with q=chef, omjindustry=72, cjfcso=1
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&omjindustry=72&cjfcso=1&q=chef",
  // 6. without omjindustry=72, but with q=chef, jt=5, cjfcso=1
  "https://jobs.ohiomeansjobs.applygovt.com/Search.aspx?cnme=Moscow&sid=29&rad=5&rad_units=miles&jt=5&cjfcso=1&q=chef"
];

for (const u of tests) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const res = await browserjs(tabId, () => {
    const text = document.body.innerText.match(/Results based on filters \(\s*([0-9,]+)\s*jobs found\s*\)/i);
    return text ? text[0] : "no count";
  });
  console.log(u.split('Search.aspx?')[1], "-->", res);
}

