const tabId = 730410078;
const fullData = await browserjs(tabId, () => {
  const container = document.querySelector('[id*="_ctl0_PageTemplateContent__ctlResultsFlat_rptResults__ctl1"]');
  if (!container) return null;

  const allText = container.innerText;
  const html = container.innerHTML;

  // Extract specific fields if present
  const labels = Array.from(container.querySelectorAll('dt, b, strong, .label')).map(el => ({
    label: el.textContent.trim(),
    next: el.nextElementSibling?.textContent.trim()
  }));

  return { allText, labels };
});
console.log(fullData);

